package sqlite

import "omni-folio/services/core/internal/storage/observation"

func ReadStatements() []observation.Statement {
	return []observation.Statement{{SQL: "SELECT COALESCE(MAX(version),0) FROM schema_migrations", Arguments: 0},
		{SQL: "SELECT recorded_at FROM owner_price_series_versions ORDER BY sequence DESC LIMIT 1", Arguments: 0},
		{SQL: "SELECT recorded_at FROM owner_fx_series_versions ORDER BY sequence DESC LIMIT 1", Arguments: 0},
		{SQL: "SELECT recorded_at FROM benchmark_series_versions ORDER BY sequence DESC LIMIT 1", Arguments: 0},
		{SQL: "SELECT sequence,event_id,event_type,authority,instrument_id,venue,symbol,currency,expected_previous_event_id,record_sha256,recorded_at\n\t\tFROM instrument_listing_events ORDER BY sequence", Arguments: 0},
		{SQL: "SELECT event_id FROM instrument_listing_events WHERE venue=? AND symbol=? AND currency=? ORDER BY sequence DESC LIMIT 1", Arguments: 3},
		{SQL: "SELECT json_extract(series_json,'$.currency'),json_extract(series_json,'$.return_basis'),json_extract(series_json,'$.source_reference'),json_extract(series_json,'$.sample') FROM benchmark_series_versions WHERE benchmark_id=? ORDER BY sequence DESC LIMIT 1", Arguments: 1},
		{SQL: "SELECT EXISTS(SELECT 1 FROM owner_price_series_versions)", Arguments: 0},
		{SQL: "SELECT b.sequence,b.series_json,b.series_sha256,b.recorded_at FROM benchmark_series_versions b JOIN (SELECT benchmark_id,MAX(sequence) AS sequence FROM benchmark_series_versions WHERE rtrim(recorded_at,'Z')<=rtrim(?,'Z') GROUP BY benchmark_id) latest ON latest.sequence=b.sequence ORDER BY b.benchmark_id", Arguments: 1},
		{SQL: "SELECT sql FROM sqlite_master WHERE name=? AND type=? AND tbl_name='benchmark_series_versions'", Arguments: 2, Objects: []string{"benchmark_series_latest_idx", "benchmark_series_versions", "benchmark_series_versions_insert_guard", "benchmark_series_versions_no_delete", "benchmark_series_versions_no_update", "fx_observations", "fx_observations_latest_idx", "fx_observations_no_delete", "fx_observations_no_update", "fx_observations_owner_pair_guard", "instrument_listing_events", "instrument_listing_events_current_idx", "instrument_listing_events_no_delete", "instrument_listing_events_no_update", "instrument_listing_events_state_guard", "owner_fx_series_latest_idx", "owner_fx_series_versions", "owner_fx_series_versions_insert_guard", "owner_fx_series_versions_no_delete", "owner_fx_series_versions_no_update", "owner_price_series_latest_idx", "owner_price_series_versions", "owner_price_series_versions_insert_guard", "owner_price_series_versions_no_delete", "owner_price_series_versions_no_update", "security_price_observations", "security_price_observations_latest_idx", "security_price_observations_no_delete", "security_price_observations_no_update", "security_price_observations_owner_guard"}, ObjectArguments: []int{0}},
		{SQL: "SELECT COUNT(*) FROM (\n        SELECT name FROM sqlite_master WHERE tbl_name='benchmark_series_versions' AND type IN ('index','trigger')\n        UNION ALL\n        SELECT name FROM sqlite_temp_master WHERE tbl_name='benchmark_series_versions' AND type IN ('index','trigger')\n    )", Arguments: 0},
		{SQL: "SELECT sequence,benchmark_id,source_version,series_json,series_sha256,recorded_at,record_sha256 FROM benchmark_series_versions ORDER BY sequence", Arguments: 0},
		{SQL: "SELECT sql FROM sqlite_master WHERE name=? AND type=? AND tbl_name=?", Arguments: 3, Objects: []string{"benchmark_series_latest_idx", "benchmark_series_versions", "benchmark_series_versions_insert_guard", "benchmark_series_versions_no_delete", "benchmark_series_versions_no_update", "fx_observations", "fx_observations_latest_idx", "fx_observations_no_delete", "fx_observations_no_update", "fx_observations_owner_pair_guard", "instrument_listing_events", "instrument_listing_events_current_idx", "instrument_listing_events_no_delete", "instrument_listing_events_no_update", "instrument_listing_events_state_guard", "owner_fx_series_latest_idx", "owner_fx_series_versions", "owner_fx_series_versions_insert_guard", "owner_fx_series_versions_no_delete", "owner_fx_series_versions_no_update", "owner_price_series_latest_idx", "owner_price_series_versions", "owner_price_series_versions_insert_guard", "owner_price_series_versions_no_delete", "owner_price_series_versions_no_update", "security_price_observations", "security_price_observations_latest_idx", "security_price_observations_no_delete", "security_price_observations_no_update", "security_price_observations_owner_guard"}, ObjectArguments: []int{0, 2}},
		{SQL: "SELECT COUNT(*) FROM (\n            SELECT name FROM sqlite_master WHERE tbl_name=? AND type IN ('index','trigger')\n            UNION ALL SELECT name FROM sqlite_temp_master WHERE tbl_name=? AND type IN ('index','trigger')\n        )", Arguments: 2, Objects: []string{"benchmark_series_latest_idx", "benchmark_series_versions", "benchmark_series_versions_insert_guard", "benchmark_series_versions_no_delete", "benchmark_series_versions_no_update", "fx_observations", "fx_observations_latest_idx", "fx_observations_no_delete", "fx_observations_no_update", "fx_observations_owner_pair_guard", "instrument_listing_events", "instrument_listing_events_current_idx", "instrument_listing_events_no_delete", "instrument_listing_events_no_update", "instrument_listing_events_state_guard", "owner_fx_series_latest_idx", "owner_fx_series_versions", "owner_fx_series_versions_insert_guard", "owner_fx_series_versions_no_delete", "owner_fx_series_versions_no_update", "owner_price_series_latest_idx", "owner_price_series_versions", "owner_price_series_versions_insert_guard", "owner_price_series_versions_no_delete", "owner_price_series_versions_no_update", "security_price_observations", "security_price_observations_latest_idx", "security_price_observations_no_delete", "security_price_observations_no_update", "security_price_observations_owner_guard"}, ObjectArguments: []int{0, 1}},
		{SQL: "SELECT EXISTS(SELECT 1 FROM owner_fx_series_versions owner JOIN fx_observations fixture ON owner.base_currency=fixture.base_currency AND owner.quote_currency=fixture.quote_currency)", Arguments: 0},
		{SQL: "SELECT sequence,base_currency,quote_currency,source_version,series_json,series_sha256,recorded_at,record_sha256 FROM owner_fx_series_versions ORDER BY sequence", Arguments: 0},
		{SQL: "SELECT o.sequence,o.series_json,o.recorded_at FROM owner_fx_series_versions o\n        JOIN (SELECT base_currency,quote_currency,MAX(sequence) AS sequence FROM owner_fx_series_versions\n            WHERE rtrim(recorded_at,'Z')<=rtrim(?,'Z') GROUP BY base_currency,quote_currency) latest ON latest.sequence=o.sequence\n        ORDER BY o.sequence", Arguments: 1},
		{SQL: "SELECT o.sequence,o.series_json,o.recorded_at FROM owner_price_series_versions o\n        JOIN (SELECT instrument_id,currency,MAX(sequence) AS sequence FROM owner_price_series_versions\n            WHERE rtrim(recorded_at,'Z')<=rtrim(?,'Z') GROUP BY instrument_id,currency) latest ON latest.sequence=o.sequence\n        ORDER BY o.sequence", Arguments: 1},
		{SQL: "SELECT observation_id,source,source_observation_id,instrument_id,symbol,venue,currency,price,price_adjustment,observed_at,fetched_at,record_sha256,recorded_at\n\t\tFROM security_price_observations WHERE source=? AND source_observation_id=?", Arguments: 2},
		{SQL: "SELECT sequence,observation_id,source,source_observation_id,instrument_id,symbol,venue,currency,price,price_adjustment,observed_at,fetched_at,record_sha256,recorded_at\n\t\tFROM security_price_observations ORDER BY sequence", Arguments: 0},
		{SQL: "SELECT EXISTS(SELECT 1 FROM owner_price_series_versions owner JOIN security_price_observations fixture ON owner.instrument_id=fixture.instrument_id AND owner.currency=fixture.currency)", Arguments: 0},
		{SQL: "SELECT sequence,instrument_id,currency,source_version,series_json,series_sha256,recorded_at,record_sha256 FROM owner_price_series_versions ORDER BY sequence", Arguments: 0},
		{SQL: "SELECT observation_id,source,source_observation_id,base_currency,quote_currency,rate,observed_at,fetched_at,record_sha256,recorded_at\n\t\tFROM fx_observations WHERE source=? AND source_observation_id=?", Arguments: 2},
		{SQL: "SELECT observation_id,source,source_observation_id,base_currency,quote_currency,rate,observed_at,fetched_at,record_sha256,recorded_at\n\t\tFROM fx_observations WHERE source=? AND base_currency=? AND quote_currency=? AND observed_at<=? AND fetched_at<=?\n\t\tORDER BY observed_at DESC,sequence DESC LIMIT 1", Arguments: 5},
		{SQL: "SELECT sequence,observation_id,source,source_observation_id,base_currency,quote_currency,rate,observed_at,fetched_at,record_sha256,recorded_at\n\t\tFROM fx_observations ORDER BY sequence", Arguments: 0}}
}
func OwnerPriceStatements() []observation.Statement {
	return []observation.Statement{{SQL: "INSERT INTO owner_price_series_versions(sequence,instrument_id,currency,source_version,series_json,series_sha256,recorded_at,record_sha256) VALUES(?,?,?,?,?,?,?,?)", Arguments: 8}}
}
